    setAppear(!appear);
    whichAppear(appear);
  }

  function whichAppear(value) {
    switch (value) {
      case true:
        console.log("a");
        break;
      case false:
        console.log("b");

        break;
    }
  }

  return (
    <div className="mainAppear">
      <div className="buttons">
        {buttonArr.map((elm) => (
          <button key={elm} className="forAppear" onClick={showHide}>
            {elm}
          </button>
        ))}
      </div>
    </div>
  );
}

export default Appear;
